-- Aman untuk mengurangi item yang terlalu banyak:
-- item yang TIDAK ada di file KStok akan di-ARSIPKAN, bukan dihapus permanen.
-- Riwayat transaksi lama tetap aman.

alter table public.items
add column if not exists pcs_per_dus numeric not null default 0,
add column if not exists item_code text null,
add column if not exists archived boolean not null default false,
add column if not exists varian text null,
add column if not exists ukuran text null,
add column if not exists deskripsi text null,
add column if not exists lokasi text null,
add column if not exists supplier text null,
add column if not exists qc_status text not null default 'OK',
add column if not exists batch_lot text null,
add column if not exists expired_date date null;

create index if not exists idx_items_category on public.items (category);
create index if not exists idx_items_lokasi on public.items (lokasi);
create index if not exists idx_items_qc_status on public.items (qc_status);
create index if not exists idx_items_expired_date on public.items (expired_date);
create index if not exists idx_items_name_lower on public.items (lower(name));
create index if not exists idx_items_item_code on public.items (item_code);

