)
-- 1) Arsipkan item lama yang tidak ada di file KStok.
update public.items i
set archived = true
where coalesce(i.archived,false) = false
  and not exists (
    select 1
    from matched_source s
    where (nullif(s.item_code,'') is not null and nullif(i.item_code,'') = nullif(s.item_code,''))
       or (lower(trim(i.name)) = lower(trim(s.name)) and lower(trim(i.category)) = lower(trim(s.category)))
  );

