-- 2) Update item yang ketemu berdasarkan kode.
update public.items i
set
  category = s.category,
  name = s.name,
  unit = s.unit,
  min_stock = s.min_stock,
  pcs_per_dus = s.pcs_per_dus,
  item_code = nullif(s.item_code,''),
  lokasi = s.lokasi,
  supplier = s.supplier,
  qc_status = s.qc_status,
  deskripsi = s.deskripsi,
  archived = false
from source_items s
where nullif(s.item_code,'') is not null
  and nullif(i.item_code,'') = nullif(s.item_code,'');

