-- 3) Update item yang ketemu berdasarkan nama + kategori.
update public.items i
set
  unit = s.unit,
  min_stock = s.min_stock,
  pcs_per_dus = s.pcs_per_dus,
  item_code = coalesce(nullif(i.item_code,''), nullif(s.item_code,'')),
  lokasi = s.lokasi,
  supplier = s.supplier,
  qc_status = s.qc_status,
  deskripsi = s.deskripsi,
  archived = false
from source_items s
where lower(trim(i.name)) = lower(trim(s.name))
  and lower(trim(i.category)) = lower(trim(s.category));

