-- 4) Tambah item dari file KStok yang belum ada.
insert into public.items (category, name, unit, starting_stock, min_stock, pcs_per_dus, item_code, physical_stock, archived, lokasi, supplier, qc_status, deskripsi)
select
  s.category,
  s.name,
  s.unit,
  s.starting_stock,
  s.min_stock,
  s.pcs_per_dus,
  nullif(s.item_code,''),
  null,
  false,
  s.lokasi,
  s.supplier,
  s.qc_status,
  s.deskripsi
from source_items s
where not exists (
  select 1
  from public.items i
  where (nullif(s.item_code,'') is not null and nullif(i.item_code,'') = nullif(s.item_code,''))
     or (lower(trim(i.name)) = lower(trim(s.name)) and lower(trim(i.category)) = lower(trim(s.category)))
);

notify pgrst, 'reload schema';

-- Cek hasil aktif setelah sync:
select category, count(*) as jumlah_item_aktif
from public.items
where coalesce(archived,false) = false
group by category
order by category;
